mapper.select:
SELECT t.training_id AS trainingId, t.title, u.username AS trainerName, t.average_rating AS averageRating, t.trainee_count AS traineeCount, t.price, t.thumbnail_url AS thumbnailUrl, t.level, t.category, t.approval_status AS status FROM trainings t JOIN users u ON t.trainer_id = u.user_id WHERE t.trainer_id = #{trainerId}
AND ( REPLACE(t.title, ' ', '') LIKE CONCAT('%', REPLACE(#{keyword}, ' ', ''), '%') OR REPLACE(u.username, ' ', '') LIKE CONCAT('%', REPLACE(#{keyword}, ' ', ''), '%') )
ORDER BY t.created_at DESC
